function smallestStart(deltas: number[]): number {
  for (let start = 1; ; start++) {
    let bal = start, ok = true;
    for (const d of deltas) {
      bal += d;
      if (bal < 1) { ok = false; break; }
    }
    if (ok) return start;
  }
}

